# Frungz : carte « Frungz Plaza », générée par cartes/construire.mjs depuis cartes/centre/plan.json. Ne pas retoucher à la main : relancer le générateur.
import bpy, bmesh
for o in list(bpy.data.objects): bpy.data.objects.remove(o, do_unlink=True)
col = bpy.data.collections.get("FRUNGZ_MAP") or bpy.data.collections.new("FRUNGZ_MAP")
if col.name not in bpy.context.scene.collection.children: bpy.context.scene.collection.children.link(col)
MATS = {"glass":["#9fd0ea",0.08,0.1],"marchandise":["#6a5a8a",0.6,0.1],"asphalte":["#3a3d42",0.92,0],"trottoir":["#a9a69e",0.85,0],"marquage":["#e8e8e2",0.8,0],"beton":["#9a9890",0.9,0],"vert":["#4f8a46",0.9,0],"tronc":["#5a4030",0.9,0],"leaf":["#3f7a3a",0.85,0],"bois":["#8a6440",0.7,0],"facade_ocre":["#d9a95b",0.75,0],"enseigne":["#ffcf4a",0.5,0,"#ffb030"],"metal":["#5d636b",0.4,0.8],"verriere":["#8fc4e6",0.1,0.2],"metal_clair":["#a8b0b8",0.35,0.8],"camion":["#e4e4e0",0.5,0.3],"conteneur_bleu":["#2f5f9a",0.6,0.4],"pneu":["#1b1c1e",0.9,0],"conteneur_vert":["#3f7a4a",0.6,0.4],"conteneur_rouge":["#b23a2c",0.6,0.4],"conteneur_ocre":["#c98a2c",0.6,0.4],"glow":["#fff3d6",0.5,0,"#ffd890"],"dallage":["#d8d2c4",0.35,0],"facade":["#e9e4d8",0.8,0],"facade_gris":["#7d848c",0.6,0.2],"cloison":["#f2efe8",0.7,0],"dallage_etage":["#cfc8b8",0.4,0],"glassRail":["#bfe3f2",0.08,0.1],"toit":["#b7b4ac",0.9,0],"eau":["#3f7fb0",0.05,0.1],"lointain":["#8f99a6",0.95,0]}
def mat(n):
    m = bpy.data.materials.get(n)
    if m: return m
    c, r, me = MATS[n][0], MATS[n][1], MATS[n][2]
    m = bpy.data.materials.new(n); m.use_nodes = True; b = m.node_tree.nodes["Principled BSDF"]
    rgb = [pow(int(c[i:i+2], 16) / 255, 2.2) for i in (1, 3, 5)]
    b.inputs["Base Color"].default_value = (*rgb, 1); b.inputs["Roughness"].default_value = r; b.inputs["Metallic"].default_value = me
    if len(MATS[n]) > 3: e = MATS[n][3]; b.inputs["Emission Color"].default_value = (*[pow(int(e[i:i+2], 16) / 255, 2.2) for i in (1, 3, 5)], 1); b.inputs["Emission Strength"].default_value = 1.5
    if n in ("glass", "glassRail", "verriere", "eau"): b.inputs["Alpha"].default_value = 0.45
    return m
def obj(name, m, V, F):
    me = bpy.data.meshes.new(name); me.from_pydata([(v[0], -v[2], v[1]) for v in V], [], F); me.update()
    o = bpy.data.objects.new(name, me); o.data.materials.append(mat(m)); col.objects.link(o); return o
